const {chromium}=require('playwright');const path=require('path');
const root=path.resolve(__dirname,'../..');
(async()=>{const browser=await chromium.launch({executablePath:'/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',headless:true,args:['--allow-file-access-from-files']});const page=await browser.newPage({viewport:{width:1510,height:930},deviceScaleFactor:1.5});const errors=[];page.on('pageerror',e=>errors.push(String(e)));await page.goto('file://'+root+'/Sembang Phone Preview.html');await page.waitForFunction(()=>window.modelsReady);
for(const view of ['angle','front','back','screen']){await page.evaluate(v=>window.setView(v),view);await page.waitForTimeout(550);await page.screenshot({path:root+'/phone/preview_'+view+'.png',fullPage:true});}
await page.setInputFiles('#upload',root+'/camera/screen_placeholder.png');await page.waitForFunction(()=>document.querySelector('#status').textContent.includes('screen_placeholder.png'));
const custom=page.waitForEvent('download');await page.click('#save');const output=await custom;await output.saveAs(root+'/phone/Burgundy_Flagship_Phone_Custom_Screen.glb');
await page.click('#reset');await page.waitForFunction(()=>document.querySelector('#status').textContent==='Neutral matte-gray placeholder');
await page.click('#spin');const before=await page.evaluate(()=>window.phoneViewer.model.rotation.y);await page.waitForTimeout(600);const after=await page.evaluate(()=>window.phoneViewer.model.rotation.y);if(after<=before)throw Error('Rotation failed');
const original=page.waitForEvent('download');await page.click('#download');if((await original).suggestedFilename()!=='Burgundy_Flagship_Phone.glb')throw Error('Wrong download');await page.setViewportSize({width:390,height:844});await page.waitForTimeout(400);if(await page.evaluate(()=>document.documentElement.scrollWidth>innerWidth))throw Error('Mobile overflow');console.log(JSON.stringify({errors,views:true,screenImage:true,customExport:true,rotation:true,mobile:true}));if(errors.length)throw Error(errors.join('\\n'));await browser.close();})().catch(error=>{console.error(error);process.exit(1)});
